=== FILE: rr_arbiter.v ===
`timescale 1ns/1ps
// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Requirement : req-142be1ce31, a round-robin arbiter for four requesters.
// Interface   : interface_spec.md (parameters, ports, behavior, reset).
// Design      : microarchitecture.md sections 1-4 (one pointer, wrapping
//               priority search against LAST, pointer to one past the winner).
// Reset       : rst_n, active low, synchronous. grant is not gated by reset.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST32 = N - 1;
    localparam [31:0]   ONE32  = 1;
    localparam [PW-1:0] LAST   = LAST32[PW-1:0];
    localparam [PW-1:0] ONE    = ONE32[PW-1:0];
    localparam [PW-1:0] ZERO   = {PW{1'b0}};

    // State: the priority pointer (microarchitecture section 1).
    reg [PW-1:0] ptr;

    // Combinational signals.
    reg [PW-1:0] ptr_nxt;
    reg [PW-1:0] winner;
    reg [PW-1:0] cand;
    reg          found;
    integer      i;

    // Grant logic: walk from ptr upwards, wrapping from LAST to 0
    // (microarchitecture section 2). Every output has a default first.
    always @* begin
        grant  = {N{1'b0}};
        winner = ZERO;
        found  = 1'b0;
        cand   = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[cand]) begin
                found       = 1'b1;
                winner      = cand;
                grant[cand] = 1'b1;
            end
            if (cand == LAST) cand = ZERO;
            else              cand = cand + ONE;
        end
    end

    // Pointer update: one past the winner on a grant, hold otherwise
    // (microarchitecture section 3).
    always @* begin
        ptr_nxt = ptr;
        if (found) begin
            if (winner == LAST) ptr_nxt = ZERO;
            else                ptr_nxt = winner + ONE;
        end
    end

    // Pointer register: synchronous active-low reset to 0 (section 4).
    always @(posedge clk) begin
        if (!rst_n) ptr <= ZERO;
        else        ptr <= ptr_nxt;
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec section 6,
    // microarchitecture section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume (!rst_n);

    // Distance from the pointer to the winner, in round-robin order.
    wire [31:0] f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(*) begin
        if (f_past_valid) assert (ptr <= LAST);
        assert ((grant & (grant - 1'b1)) == {N{1'b0}});
        assert ((grant & ~req) == {N{1'b0}});
        assert ((|req) == (|grant));
        assert (found == (|req));
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n))
            assert (ptr == ZERO);
        if (f_past_valid && $past(rst_n) && $past(found))
            assert (ptr == (($past(winner) == LAST) ? ZERO : ($past(winner) + ONE)));
        if (f_past_valid && $past(rst_n) && !$past(found))
            assert (ptr == $past(ptr));
        if (f_past_valid && $past(rst_n) && $past(found) && ($past(winner) == LAST))
            cover (ptr == ZERO);
    end

    always @(*) cover (f_past_valid && rst_n && (&req));

    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : f_req
            reg  [31:0] f_wait;
            wire [31:0] f_dist = (g >= ptr) ? (g - ptr) : (g + N - ptr);

            always @(posedge clk) begin
                if (!rst_n)                   f_wait <= 32'd0;
                else if (req[g] && !grant[g]) f_wait <= f_wait + 32'd1;
                else                          f_wait <= 32'd0;
            end

            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                end
                if (found && req[g]) assert (f_dist >= f_wdist);
            end

            always @(*) cover (f_past_valid && rst_n && grant[g]);
        end
    endgenerate
`endif

endmodule
=== END FILE ===
