`timescale 1ns/1ps
// Self-checking testbench for rr_arbiter (interface_spec section 6,
// microarchitecture section 5): two lanes, N=4 and N=5, each checked every
// cycle against a reference pointer model, with fairness counters and
// coverage goals that fail the run if not reached.

module rr_arbiter_tb_lane #(
    parameter integer N    = 4,
    parameter integer SEED = 1
) (
    input  wire        clk,
    output reg  [31:0] n_pass,
    output reg  [31:0] n_fail,
    output reg         done
);
    localparam [N-1:0] ONE_N = {{(N-1){1'b0}}, 1'b1};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Reference model and fairness state.
    integer     mptr;
    integer     wait_cnt [0:N-1];
    reg [N-1:0] prev_req;
    reg         prev_live;
    reg         traffic_seen;
    integer     cyc;

    // Coverage goals.
    reg         cov_none;
    reg         cov_all;
    reg         cov_held;
    reg         cov_maxwait;
    reg         cov_rst_traffic;
    reg [N-1:0] cov_alone;

    // Working variables. j, k belong to check_cycle; t, h to the stimulus.
    reg [31:0]  lfsr;
    reg [N-1:0] exp_g;
    reg [N-1:0] r_tmp;
    reg         found;
    reg         others_changed;
    integer     win, idx, cnt;
    integer     j, k;
    integer     t, h;

    function [N-1:0] bit_of;
        input integer b;
        integer m;
        begin
            bit_of = {N{1'b0}};
            for (m = 0; m < N; m = m + 1)
                if (m == b) bit_of[m] = 1'b1;
        end
    endfunction

    task ok;
        begin
            n_pass = n_pass + 32'd1;
        end
    endtask

    task bad;
        begin
            n_fail = n_fail + 32'd1;
        end
    endtask

    task next_rand;
        begin
            lfsr = lfsr ^ (lfsr << 13);
            lfsr = lfsr ^ (lfsr >> 17);
            lfsr = lfsr ^ (lfsr << 5);
        end
    endtask

    // Check the current cycle, then advance the model as the coming rising
    // edge will advance the DUT.
    task check_cycle;
        begin
            // Model: first requester at or after mptr, wrapping at N.
            exp_g = {N{1'b0}};
            found = 1'b0;
            win   = 0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (mptr + k) % N;
                for (j = 0; j < N; j = j + 1)
                    if (!found && (j == idx) && req[j]) begin
                        found = 1'b1;
                        win   = j;
                    end
            end
            for (j = 0; j < N; j = j + 1)
                exp_g[j] = found && (j == win);

            if (grant === exp_g) ok;
            else begin
                $error("rr_arbiter N=%0d cycle %0d: rst_n %b req %b model ptr %0d: grant %b, expected %b",
                       N, cyc, rst_n, req, mptr, grant, exp_g);
                bad;
            end

            // Independent properties: one-hot or zero, only to a requester,
            // work conserving.
            if (((grant & (grant - ONE_N)) == {N{1'b0}}) &&
                ((grant & ~req) == {N{1'b0}}) &&
                ((|req) == (|grant))) ok;
            else begin
                $error("rr_arbiter N=%0d cycle %0d: grant property broken: req %b grant %b",
                       N, cyc, req, grant);
                bad;
            end

            // Fairness: a held request waits at most N-1 cycles.
            for (j = 0; j < N; j = j + 1) begin
                if (!rst_n || !req[j]) begin
                    wait_cnt[j] = 0;
                end else if (grant[j]) begin
                    if (wait_cnt[j] == N - 1) cov_maxwait = 1'b1;
                    if (wait_cnt[j] <= N - 1) ok;
                    wait_cnt[j] = 0;
                end else begin
                    wait_cnt[j] = wait_cnt[j] + 1;
                    if (wait_cnt[j] > N - 1) begin
                        $error("rr_arbiter N=%0d cycle %0d: requester %0d has waited %0d cycles (bound %0d)",
                               N, cyc, j, wait_cnt[j], N - 1);
                        bad;
                    end
                end
            end

            // Coverage.
            cnt = 0;
            for (j = 0; j < N; j = j + 1)
                if (req[j]) cnt = cnt + 1;
            if (rst_n) begin
                if (req == {N{1'b0}}) cov_none = 1'b1;
                if (&req) cov_all = 1'b1;
                for (j = 0; j < N; j = j + 1)
                    if ((cnt == 1) && req[j]) cov_alone[j] = 1'b1;
                if (|req) traffic_seen = 1'b1;
                if (prev_live) begin
                    for (j = 0; j < N; j = j + 1) begin
                        if (req[j] && prev_req[j]) begin
                            others_changed = 1'b0;
                            for (k = 0; k < N; k = k + 1)
                                if ((k != j) && (req[k] != prev_req[k])) others_changed = 1'b1;
                            if (others_changed) cov_held = 1'b1;
                        end
                    end
                end
            end else if (traffic_seen && (|req)) begin
                cov_rst_traffic = 1'b1;
            end

            // Advance the model to the state after the coming edge.
            if (!rst_n)     mptr = 0;
            else if (found) mptr = (win + 1) % N;
            prev_req  = req;
            prev_live = rst_n;
            cyc       = cyc + 1;
        end
    endtask

    // One cycle: drive on the falling edge, check once logic has settled.
    task step;
        input [N-1:0] r;
        input         rs;
        begin
            @(negedge clk);
            req   = r;
            rst_n = rs;
            #1;
            check_cycle;
        end
    endtask

    initial begin
        n_pass          = 32'd0;
        n_fail          = 32'd0;
        done            = 1'b0;
        rst_n           = 1'b0;
        req             = {N{1'b0}};
        mptr            = 0;
        cyc             = 0;
        prev_req        = {N{1'b0}};
        prev_live       = 1'b0;
        traffic_seen    = 1'b0;
        cov_none        = 1'b0;
        cov_all         = 1'b0;
        cov_held        = 1'b0;
        cov_maxwait     = 1'b0;
        cov_rst_traffic = 1'b0;
        cov_alone       = {N{1'b0}};
        lfsr            = SEED;
        for (t = 0; t < N; t = t + 1) wait_cnt[t] = 0;

        // Reset for two edges before the first check.
        repeat (2) @(posedge clk);

        // 1. Requests during reset: grant follows req, the pointer stays 0.
        step({N{1'b1}}, 1'b0);
        step({N{1'b1}}, 1'b0);

        // 2. No requests: no grant, the pointer holds.
        step({N{1'b0}}, 1'b1);
        step({N{1'b0}}, 1'b1);

        // 3. Each requester alone.
        for (t = 0; t < N; t = t + 1) begin
            step(bit_of(t), 1'b1);
            step(bit_of(t), 1'b1);
        end

        // 4. Reset during traffic, then everyone requesting: strict rotation
        //    0, 1, ..., N-1, 0, ... and the longest fair wait (N-1).
        step({N{1'b1}}, 1'b0);
        for (t = 0; t < 3 * N; t = t + 1) begin
            step({N{1'b1}}, 1'b1);
            if (grant === bit_of(t % N)) ok;
            else begin
                $error("rr_arbiter N=%0d rotation step %0d: grant %b, expected %b",
                       N, t, grant, bit_of(t % N));
                bad;
            end
        end

        // 5. A held request among changing others (requester 0, then N-1).
        for (h = 0; h < N; h = h + (N - 1)) begin
            for (t = 0; t < 4 * N; t = t + 1) begin
                next_rand;
                step(lfsr[N-1:0] | bit_of(h), 1'b1);
            end
        end

        // 6. Requests dropped and raised again.
        for (t = 0; t < 2 * N; t = t + 1) begin
            step({N{1'b1}} & ~bit_of(t % N), 1'b1);
            step({N{1'b1}}, 1'b1);
        end

        // 7. Random subsets, with a reset in the middle of traffic.
        for (t = 0; t < 300; t = t + 1) begin
            next_rand;
            r_tmp = lfsr[N-1:0];
            if (lfsr[20]) r_tmp = r_tmp | lfsr[N+7:8];
            if (lfsr[21] && lfsr[22]) r_tmp = r_tmp & lfsr[N+15:16];
            if ((t >= 150) && (t < 152)) begin
                step(r_tmp | bit_of(1), 1'b0);
            end else begin
                step(r_tmp, 1'b1);
            end
        end

        // 8. Quiet end.
        step({N{1'b0}}, 1'b1);

        // Coverage goals from interface_spec section 6.
        if (cov_none) ok;
        else begin $error("rr_arbiter N=%0d coverage: no-request cycle not reached", N); bad; end
        if (&cov_alone) ok;
        else begin $error("rr_arbiter N=%0d coverage: requester alone not reached for all (%b)", N, cov_alone); bad; end
        if (cov_all) ok;
        else begin $error("rr_arbiter N=%0d coverage: everyone requesting not reached", N); bad; end
        if (cov_held) ok;
        else begin $error("rr_arbiter N=%0d coverage: held request among changing others not reached", N); bad; end
        if (cov_maxwait) ok;
        else begin $error("rr_arbiter N=%0d coverage: longest fair wait (N-1) not reached", N); bad; end
        if (cov_rst_traffic) ok;
        else begin $error("rr_arbiter N=%0d coverage: reset during traffic not reached", N); bad; end

        done = 1'b1;
    end
endmodule

module rr_arbiter_tb;
    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    wire [31:0] pass4;
    wire [31:0] fail4;
    wire [31:0] pass5;
    wire [31:0] fail5;
    wire        done4;
    wire        done5;

    rr_arbiter_tb_lane #(.N(4), .SEED(32'h1F2E3D4C)) lane4 (
        .clk    (clk),
        .n_pass (pass4),
        .n_fail (fail4),
        .done   (done4)
    );

    rr_arbiter_tb_lane #(.N(5), .SEED(32'h2468ACE1)) lane5 (
        .clk    (clk),
        .n_pass (pass5),
        .n_fail (fail5),
        .done   (done5)
    );

    reg [8*64-1:0] nonce;
    reg [31:0]     passed;
    reg [31:0]     failed;
    reg            finished;

    initial finished = 1'b0;

    task finish_run;
        input [31:0] extra_fail;
        begin
            if (!finished) begin
                finished = 1'b1;
                passed   = pass4 + pass5;
                failed   = fail4 + fail5 + extra_fail;
                nonce    = {(8*64){1'b0}};
                if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
                    nonce = {(8*64){1'b0}};
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        while ((done4 !== 1'b1) || (done5 !== 1'b1)) @(posedge clk);
        @(posedge clk);
        finish_run(32'd0);
    end

    initial begin
        #2000000;
        $error("rr_arbiter_tb: timeout, lanes done %b %b", done4, done5);
        finish_run(32'd1);
    end
endmodule
=== END FILE ===
